    Set-ProbeRoot $repo
    $positives = @(
        @{ Input = $prefix+'powershell_duplicate_function_report.json'; Suffix = '.json'; Relative = $prefix+'powershell_duplicate_function_report.json' }
        @{ Input = 'project_sources\collector\powershell_duplicate_function_report.md'; Suffix = '.md'; Relative = $prefix+'powershell_duplicate_function_report.md' }
        @{ Input = 'project_sources\collector/nested\report.json'; Suffix = '.json'; Relative = $prefix+'nested/report.json' }
        @{ Input = '  '+$prefix+'report.json  '; Suffix = '.json'; Relative = $prefix+'report.json' }
        @{ Input = $prefix+'report.JSON'; Suffix = '.json'; Relative = $prefix+'report.JSON' }
        @{ Input = $prefix+'nested/report.md'; Suffix = '.md'; Relative = $prefix+'nested/report.md' }
        @{ Input = $prefix+'name..part.json'; Suffix = '.json'; Relative = $prefix+'name..part.json' }
        @{ Input = $prefix+'existing/report.json'; Suffix = '.json'; Relative = $prefix+'existing/report.json' }
        @{ Input = $prefix+'existing/new.json'; Suffix = '.json'; Relative = $prefix+'existing/new.json' }
        @{ Input = $prefix+'fresh/deep/report.json'; Suffix = '.json'; Relative = $prefix+'fresh/deep/report.json' }
        @{ Input = $prefix+'literal [x]/report name.json'; Suffix = '.json'; Relative = $prefix+'literal [x]/report name.json' }
        @{ Input = $prefix+'LPT10.json'; Suffix = '.json'; Relative = $prefix+'LPT10.json' }
    )
    $safe = 0
    foreach ($case in $positives) {
        $r = @(Resolve-CollectorReportPath $case.Input 'Test' $case.Suffix)
        $expected = [IO.Path]::Combine($repo,$case.Relative.Replace('/',[string][IO.Path]::DirectorySeparatorChar))
        if ($r.Count -ne 1 -or $r[0].RelativePath -cne $case.Relative -or $r[0].FullPath -cne $expected) { throw "Safe legacy control failed: $($case.Relative)" }
        $safe++
    }
    if ($safe -ne 12 -or [IO.File]::ReadAllText($ordinary) -cne 'ordinary-sentinel' -or [IO.Directory]::Exists((Join-Path $collector 'fresh'))) { throw 'Ordinary fixture changed' }
    Write-Output "BASELINE=$baseline BLOB=$blob PWSH=$($PSVersionTable.PSVersion) SAFE_CONTROLS=$safe"
    $syntax = @('nested//report.json','./report.json','.../report.json','name./report.json','name /report.json','report:stream.json','name:part/report.json','bad*/report.json','bad?/report.json','<bad>/report.json','bad"/report.json','bad|/report.json','con.json','NUL .json','aux/report.json','PRN.json','COM1.json','LPT9/report.json',('COM'+[char]0x00B9+'.json'),('LPT'+[char]0x00B3+'.json'),'CONIN$.json','CONOUT$.json')
    for ($index=0;$index -lt $syntax.Count;$index++) { Show-LegacyResult "syntax-$($index+1)" ($prefix+$syntax[$index]) }
    if ($syntax.Count -ne 22) { throw 'Syntax case count mismatch' }
    $md = ConvertTo-MarkdownTableCell ('name'+[char]96+'with|table'+[char]10+'<&>')
    if ($md -cne 'name&#96;with&#124;table &lt;&amp;&gt;') { throw 'Markdown control failed' }
